<?php require 'autorizare.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim($_POST['titlu']??'');$author=trim($_POST['autor']??'');$domain=trim($_POST['domeniu']??'');$desc=trim($_POST['descriere']??'');$price=(float)($_POST['pret']??0);if($title&&$author&&$domain){$pdo->beginTransaction();$s=$pdo->prepare('SELECT id_autor FROM autori WHERE nume_autor=?');$s->execute([$author]);$aid=$s->fetchColumn();if(!$aid){$s=$pdo->prepare('INSERT INTO autori(nume_autor) VALUES(?)');$s->execute([$author]);$aid=$pdo->lastInsertId();}$s=$pdo->prepare('SELECT id_domeniu FROM domenii WHERE nume_domeniu=?');$s->execute([$domain]);$did=$s->fetchColumn();if(!$did){$s=$pdo->prepare('INSERT INTO domenii(nume_domeniu) VALUES(?)');$s->execute([$domain]);$did=$pdo->lastInsertId();}$s=$pdo->prepare('INSERT INTO carti(id_autor,id_domeniu,titlu,descriere,pret,data) VALUES(?,?,?,?,?,NOW())');$s->execute([$aid,$did,$title,$desc,$price]);$pdo->commit();$msg='Cartea a fost adaugata.';}}include 'admin_top.php';?><p><b><?=h($msg)?></b></p><form method="post"><p>Titlu: <input name="titlu" required></p><p>Autor: <input name="autor" required></p><p>Domeniu: <input name="domeniu" required></p><p>Pret: <input name="pret" type="number" min="0" step="0.01" required></p><p>Descriere:<br><textarea name="descriere" rows="8" cols="60"></textarea></p><button>Adauga</button></form></body></html>
